from odoo import fields, models
from odoo.tools import float_is_zero

NUMERIC_TYPES = ("integer", "float", "monetary")


def format_zero(field, value):
    """How the ECF writes a numeric field that is zero, or None if not zero.

    The layout tells a mandatory field from an optional one: the mandatory
    zero is written as ``0`` (the PVA refuses the register with the field
    blank, as in 0000.TIP_ECF or the K155 balances), the optional one stays
    blank (0000.PAT_REMAN_CIS outside a split-up). sped_base decides the
    zero by the field type alone (blank for integer and monetary, ``0`` for
    float), so the rule lives here.
    """
    if field.type not in NUMERIC_TYPES:
        return None
    if not float_is_zero(value or 0.0, precision_digits=8):
        return None
    return "0" if field.required else ""


